/**
 * Generates the per-area detail data files from authored copy.
 *
 *   node scripts/build-detail-data.mjs area  <journal.jsonl>
 *   node scripts/build-detail-data.mjs combo <combo-detail.json>
 *
 * Writes src/data/area-detail.ts, or the four src/data/combo-detail-*.ts
 * files. Kept in the repo so the copy can be regenerated or diffed rather
 * than being an unexplained blob. The generated files are the source of
 * truth once written — edit them directly and this script is only needed
 * if the copy is reauthored wholesale.
 *
 * area  input: a workflow journal, one {"type":"result", ...} line per agent.
 * combo input: a JSON object of { serviceSlug: { areaSlug: entry } }.
 */
import fs from "node:fs";

const [mode, inputPath] = process.argv.slice(2);
if (!mode || !inputPath) {
  console.error("usage: build-detail-data.mjs <area|combo> <input>");
  process.exit(1);
}

const readJournal = () =>
  fs
    .readFileSync(inputPath, "utf8")
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      try {
        return JSON.parse(line);
      } catch {
        return null;
      }
    })
    .filter((o) => o && o.type === "result")
    .map((o) => o.result ?? o.value)
    .filter(Boolean);

/** TypeScript string literal: double-quoted, escaped, no template syntax. */
const lit = (s) =>
  `"${String(s).replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, " ").replace(/\s+/g, " ").trim()}"`;

const faqList = (faqs, indent) =>
  faqs
    .map(
      (f) =>
        `${indent}  {\n${indent}    q: ${lit(f.q)},\n${indent}    a: ${lit(f.a)},\n${indent}  },`,
    )
    .join("\n");

const HEADER = `// Generated by scripts/build-detail-data.mjs — edit the copy here directly;
// re-running the generator overwrites this file.
`;

if (mode === "area") {
  const merged = {};
  for (const r of readJournal()) for (const e of r.entries ?? []) merged[e.areaSlug] = e;
  const slugs = Object.keys(merged).sort();
  const body = slugs
    .map((slug) => {
      const e = merged[slug];
      return `  ${JSON.stringify(slug)}: {
    streets: ${lit(e.streets)},
    buildings: ${lit(e.buildings)},
    access: ${lit(e.access)},
    extraFaqs: [
${faqList(e.extraFaqs, "    ")}
    ],
  },`;
    })
    .join("\n");

  fs.writeFileSync(
    "src/data/area-detail.ts",
    `${HEADER}import type { Faq } from "./types";

/**
 * Deeper per-area copy layered onto AreaHubContent. Area hubs were the
 * thinnest of the three core templates; these fields carry the housing
 * detail that makes each of the 25 pages worth reading on its own.
 */
export type AreaDetail = {
  /** Named streets and sub-neighbourhoods, and the stock on them. */
  streets: string;
  /** Recurring building types and what they mean for interior work. */
  buildings: string;
  /** Parking, loading, skips and access specifics. */
  access: string;
  /** Additional hand-written questions, merged after the existing faqs. */
  extraFaqs: Faq[];
};

export const areaDetail: Record<string, AreaDetail> = {
${body}
};
`,
  );
  console.log(`src/data/area-detail.ts: ${slugs.length} areas`);
  process.exit(0);
}

if (mode === "combo") {
  const SERVICES = {
    "kitchen-renovation": ["kitchenDetail", "src/data/combo-detail-kitchen.ts"],
    "bathroom-renovation": ["bathroomDetail", "src/data/combo-detail-bathroom.ts"],
    "painting-decorating": ["paintingDetail", "src/data/combo-detail-painting.ts"],
    "light-refurbishment": ["refurbDetail", "src/data/combo-detail-refurb.ts"],
  };
  const byService = JSON.parse(fs.readFileSync(inputPath, "utf8"));
  for (const [service, [name, file]] of Object.entries(SERVICES)) {
    const entries = byService[service] ?? {};
    const slugs = Object.keys(entries).sort();
    const body = slugs
      .map((slug) => {
        const e = entries[slug];
        return `  ${JSON.stringify(slug)}: {
    scopeNotes: [
${e.scopeNotes.map((p) => `      ${lit(p)},`).join("\n")}
    ],
    processNote: ${lit(e.processNote)},
    consent: ${lit(e.consent)},
    extraFaqs: [
${faqList(e.extraFaqs, "    ")}
    ],
  },`;
      })
      .join("\n");
    fs.writeFileSync(
      file,
      `${HEADER}import type { ComboDetailMap } from "./combo-detail";

export const ${name}: ComboDetailMap = {
${body}
};
`,
    );
    console.log(`${file}: ${slugs.length} areas`);
  }
  process.exit(0);
}

console.error(`unknown mode: ${mode}`);
process.exit(1);
